import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../core/api_client.dart';
import '../providers/providers.dart';
class AdminReportsScreen extends ConsumerStatefulWidget{const AdminReportsScreen({super.key});@override ConsumerState<AdminReportsScreen> createState()=>_R();}
class _R extends ConsumerState<AdminReportsScreen>{Map<String,dynamic>? data;bool loading=true;String? error;@override void initState(){super.initState();_load();}Future<void>_load()async{try{final d=(await ref.read(apiClientProvider).get('/api/admin/reports') as Map).cast<String,dynamic>();if(mounted)setState((){data=d;loading=false;});}catch(e){if(mounted)setState((){error=e is ApiException?e.message:'$e';loading=false;});}}
@override Widget build(BuildContext context)=>RefreshIndicator(onRefresh:_load,child:loading?ListView(children:const[SizedBox(height:260),Center(child:CircularProgressIndicator())]):ListView(padding:const EdgeInsets.all(16),children:[const Text('Reports & Analytics',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900,color:Color(0xFF071A63))),const Text('Live platform metrics from the database.',style:TextStyle(color:Color(0xFF62729B))),const SizedBox(height:16),if(error!=null)Text(error!),...['businesses','contacts','templates','automations','messages'].map((k)=>_section(k,(data?[k] as Map?)?.cast<String,dynamic>()??{}))]));
Widget _section(String title,Map<String,dynamic> m)=>Card(margin:const EdgeInsets.only(bottom:12),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title[0].toUpperCase()+title.substring(1),style:const TextStyle(fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:12),Wrap(spacing:10,runSpacing:10,children:m.entries.map((e)=>Container(width:135,padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:const Color(0xFFF4F8FF),borderRadius:BorderRadius.circular(12)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e.value}',style:const TextStyle(fontSize:22,fontWeight:FontWeight.w900,color:Color(0xFF071A63))),Text(e.key.replaceAll('_',' '),style:const TextStyle(color:Color(0xFF62729B)))]))).toList())])));
}
